// ============================================================================
// Smartcard_7816_apb: APB4 register wrapper around Smartcard_7816_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/Smartcard_7816.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/Smartcard_7816.md
// ============================================================================
module Smartcard_7816_apb #(
  parameter logic [3:0] AXI_ID = 4'd10
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic sc_vcc_en,
  output logic sc_rst_n,
  output logic sc_clk,
  input logic sc_io_in,
  output logic sc_io_oe_low,
  input logic sc_det,
  output logic [3:0] m_awid,
  output logic [31:0] m_awaddr,
  output logic [7:0] m_awlen,
  output logic [2:0] m_awsize,
  output logic [1:0] m_awburst,
  output logic [2:0] m_awprot,
  output logic m_awvalid,
  input logic m_awready,
  output logic [31:0] m_wdata,
  output logic [3:0] m_wstrb,
  output logic m_wlast,
  output logic m_wvalid,
  input logic m_wready,
  input logic [3:0] m_bid,
  input logic [1:0] m_bresp,
  input logic m_bvalid,
  output logic m_bready,
  output logic [3:0] m_arid,
  output logic [31:0] m_araddr,
  output logic [7:0] m_arlen,
  output logic [2:0] m_arsize,
  output logic [1:0] m_arburst,
  output logic [2:0] m_arprot,
  output logic m_arvalid,
  input logic m_arready,
  input logic [3:0] m_rid,
  input logic [31:0] m_rdata,
  input logic [1:0] m_rresp,
  input logic m_rlast,
  input logic m_rvalid,
  output logic m_rready
);
  localparam logic [31:0] ID_VALUE = 32'h7C0A0100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [17:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd18) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_enable;
  logic          c_inverse;
  logic          c_t1;
  logic [7:0]    c_clk_div;
  logic [15:0]   c_etu;
  logic [7:0]    c_guard;
  logic [15:0]   c_wt;
  logic [15:0]   c_rst_clks;
  logic [31:0]   c_ring_base;
  logic [15:0]   c_ring_words;
  logic [15:0]   c_rd_idx;
  logic [31:0]   c_tx_addr;
  logic [15:0]   c_tx_len;
  logic          c_activate;
  logic          c_deactivate;
  logic          c_tx_start;
  logic          c_active;
  logic          c_powered;
  logic          c_tx_busy;
  logic          c_tx_fail;
  logic          c_err;
  logic          c_present;
  logic [15:0]   c_wr_idx;
  logic [15:0]   c_rx_cnt;
  logic [15:0]   c_perr_cnt;
  logic [15:0]   c_retx_cnt;
  logic [15:0]   c_ovf_cnt;
  logic          c_rx;
  logic          c_tx_done;
  logic          c_perr;
  logic          c_det;
  logic          c_timeout;
  logic          c_err_irq;
  Smartcard_7816_top #(.AXI_ID(AXI_ID)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .sc_vcc_en(sc_vcc_en),
    .sc_rst_n(sc_rst_n),
    .sc_clk(sc_clk),
    .sc_io_in(sc_io_in),
    .sc_io_oe_low(sc_io_oe_low),
    .sc_det(sc_det),
    .enable(c_enable),
    .inverse(c_inverse),
    .t1(c_t1),
    .clk_div(c_clk_div),
    .etu(c_etu),
    .guard(c_guard),
    .wt(c_wt),
    .rst_clks(c_rst_clks),
    .ring_base(c_ring_base),
    .ring_words(c_ring_words),
    .rd_idx(c_rd_idx),
    .tx_addr(c_tx_addr),
    .tx_len(c_tx_len),
    .activate(c_activate),
    .deactivate(c_deactivate),
    .tx_start(c_tx_start),
    .active(c_active),
    .powered(c_powered),
    .tx_busy(c_tx_busy),
    .tx_fail(c_tx_fail),
    .err(c_err),
    .present(c_present),
    .wr_idx(c_wr_idx),
    .rx_cnt(c_rx_cnt),
    .perr_cnt(c_perr_cnt),
    .retx_cnt(c_retx_cnt),
    .ovf_cnt(c_ovf_cnt),
    .rx(c_rx),
    .tx_done(c_tx_done),
    .perr(c_perr),
    .det(c_det),
    .timeout(c_timeout),
    .err_irq(c_err_irq),
    .m_awid(m_awid),
    .m_awaddr(m_awaddr),
    .m_awlen(m_awlen),
    .m_awsize(m_awsize),
    .m_awburst(m_awburst),
    .m_awprot(m_awprot),
    .m_awvalid(m_awvalid),
    .m_awready(m_awready),
    .m_wdata(m_wdata),
    .m_wstrb(m_wstrb),
    .m_wlast(m_wlast),
    .m_wvalid(m_wvalid),
    .m_wready(m_wready),
    .m_bid(m_bid),
    .m_bresp(m_bresp),
    .m_bvalid(m_bvalid),
    .m_bready(m_bready),
    .m_arid(m_arid),
    .m_araddr(m_araddr),
    .m_arlen(m_arlen),
    .m_arsize(m_arsize),
    .m_arburst(m_arburst),
    .m_arprot(m_arprot),
    .m_arvalid(m_arvalid),
    .m_arready(m_arready),
    .m_rid(m_rid),
    .m_rdata(m_rdata),
    .m_rresp(m_rresp),
    .m_rlast(m_rlast),
    .m_rvalid(m_rvalid),
    .m_rready(m_rready)
  );

  // ---------------- registers ----------------
  logic [5:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [10:0] r_CTRL;   // 12'h014 CTRL
  logic [23:0] r_TIMING;   // 12'h018 TIMING
  logic [31:0] r_WAITS;   // 12'h01C WAITS
  logic [31:0] r_RING_BASE;   // 12'h020 RING_BASE
  logic [15:0] r_RING_WORDS;   // 12'h024 RING_WORDS
  logic [15:0] r_RD_IDX;   // 12'h028 RD_IDX
  logic [31:0] r_TX_ADDR;   // 12'h02C TX_ADDR
  logic [15:0] r_TX_LEN;   // 12'h030 TX_LEN
  logic [2:0] p_CMD;   // 12'h034 CMD (pulses)

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CTRL <= 11'h0;
      r_TIMING <= 24'h0;
      r_WAITS <= 32'h0;
      r_RING_BASE <= 32'h0;
      r_RING_WORDS <= 16'h0;
      r_RD_IDX <= 16'h0;
      r_TX_ADDR <= 32'h0;
      r_TX_LEN <= 16'h0;
      p_CMD <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[5:0] & wmask[5:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[5:0]) | (PWDATA[5:0] & wmask[5:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CTRL <= (r_CTRL & ~wmask[10:0]) | (PWDATA[10:0] & wmask[10:0]);
      if (wr && hit[6]) r_TIMING <= (r_TIMING & ~wmask[23:0]) | (PWDATA[23:0] & wmask[23:0]);
      if (wr && hit[7]) r_WAITS <= (r_WAITS & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[8]) r_RING_BASE <= (r_RING_BASE & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[9]) r_RING_WORDS <= (r_RING_WORDS & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[10]) r_RD_IDX <= (r_RD_IDX & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[11]) r_TX_ADDR <= (r_TX_ADDR & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[12]) r_TX_LEN <= (r_TX_LEN & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      p_CMD <= (wr && hit[13]) ? PWDATA[2:0] & wmask[2:0] : '0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_enable = r_CTRL[0:0];
  assign c_inverse = r_CTRL[1:1];
  assign c_t1 = r_CTRL[2:2];
  assign c_clk_div = r_CTRL[10:3];
  assign c_etu = r_TIMING[15:0];
  assign c_guard = r_TIMING[23:16];
  assign c_wt = r_WAITS[15:0];
  assign c_rst_clks = r_WAITS[31:16];
  assign c_ring_base = r_RING_BASE[31:0];
  assign c_ring_words = r_RING_WORDS[15:0];
  assign c_rd_idx = r_RD_IDX[15:0];
  assign c_tx_addr = r_TX_ADDR[31:0];
  assign c_tx_len = r_TX_LEN[15:0];
  assign c_activate = p_CMD[0:0];
  assign c_deactivate = p_CMD[1:1];
  assign c_tx_start = p_CMD[2:2];

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_rx;
    irq_set[1] = c_tx_done;
    irq_set[2] = c_perr;
    irq_set[3] = c_det;
    irq_set[4] = c_timeout;
    irq_set[5] = c_err_irq;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CTRL);
      10'd6: apb_rdata = 32'(r_TIMING);
      10'd7: apb_rdata = 32'(r_WAITS);
      10'd8: apb_rdata = 32'(r_RING_BASE);
      10'd9: apb_rdata = 32'(r_RING_WORDS);
      10'd10: apb_rdata = 32'(r_RD_IDX);
      10'd11: apb_rdata = 32'(r_TX_ADDR);
      10'd12: apb_rdata = 32'(r_TX_LEN);
      10'd14: apb_rdata = 32'({c_present, c_err, c_tx_fail, c_tx_busy, c_powered, c_active});
      10'd15: apb_rdata = 32'({c_wr_idx});
      10'd16: apb_rdata = 32'({c_perr_cnt, c_rx_cnt});
      10'd17: apb_rdata = 32'({c_ovf_cnt, c_retx_cnt});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
